input.sparql:
SELECT ?zone ?ts ?uri ?cls WHERE {
  ?zone a brick:Zone ; rdfs:label ?lbl .
  FILTER(CONTAINS(LCASE(?lbl), "basement"))
  ?zone ?p ?temp .
  OPTIONAL { ?temp ref:hasExternalReference ?uri ; ref:hasTimeseriesId ?ts . }
}

